// ============ 顺序栈长什么样 ============
//
//   入栈 40 之后：
//
//   下标   0    1    2    3    4    5
//        ┌────┬────┬────┬────┬────┬────┐
//   data │ 10 │ 20 │ 30 │ 40 │    │    │
//        └────┴────┴────┴────┴────┴────┘
//                            ↑
//                          top = 3
//
// 关键约定：**top 指向栈顶元素本身**，而栈顶就是"最后进来的那个"。
//
//   空栈      top = -1
//   一个元素  top = 0
//   装满      top = MAXSIZE - 1
//
// ============ 为什么这样约定 ============
//
// 也有人让 top 指向"栈顶上面那个空位"，那样空栈是 top = 0。
// 两种写法都对，但**混用必出 bug**。本文件统一用"top 指栈顶元素"：
//
//   入栈：先 top++ ，再把元素放进 data[top]
//   出栈：先取走 data[top] ，再 top--
//
// 一句话记住：**top 永远指着有东西的那个格子**，它指向 -1 就是空。

// 元素类型
typedef int ElemType;

// 栈最多能装多少个
#define MAXSIZE 100

// 状态码
#define OK 1
#define ERROR 0

// 返回值类型
typedef int Status;

// 顺序栈 = 定长数组 + 栈顶下标
typedef struct
{
// 连续内存，和顺序表一样
    ElemType data[MAXSIZE];
// 栈顶元素的下标；-1 表示空栈
    int top;
} Stack;

