modes.detail:
// ============ 用输出验证"后进先出" ============
//
// 依次压入 10、20、30，再连续弹出，出来的顺序是 30、20、10 ——
// 和进去的顺序**正好相反**。这就是 LIFO（Last In First Out）。
//
// 别小看这一条：后面表达式求值、括号匹配、递归、DFS 全靠它。

// 打印当前栈里的内容（从栈底到栈顶）
static void PrintStack(const char *tag, Stack S)
{
    int i;

    printf("%s top=%d : ", tag, S.top);
    for (i = 0; i <= S.top; i++)
    {
        printf("%d ", S.data[i]);
    }
    printf("\n");
}

// 主函数
int main(void)
{
// 定义一张栈
    Stack S;
// 用来接住弹出的元素
    ElemType e;

// 先初始化
    InitStack(&S);
    PrintStack("初始化后:", S);

// 依次压入 10、20、30
    Push(&S, 10);
    Push(&S, 20);
    Push(&S, 30);
    PrintStack("压入 10 20 30 后:", S);

// 弹一个出来 —— 应该是最后进去的 30
    if (Pop(&S, &e) == OK)
    {
        printf("弹出一个 -> %d（最后进去的最先出来）\n", e);
    }
    PrintStack("弹出后:", S);

// 把剩下的都弹光，看顺序
    printf("继续弹出: ");
    while (Pop(&S, &e) == OK)
    {
        printf("%d ", e);
    }
    printf("\n");
    PrintStack("弹空后:", S);

// 空栈再弹应该被挡住
    if (Pop(&S, &e) == ERROR)
    {
        printf("空栈弹出 -> 被拒绝（top == -1）\n");
    }

// 压满再压一个，也应该被挡住
// 这一次循环压 MAXSIZE 个，正好压满（top 到 MAXSIZE-1）
    {
        int i;
        for (i = 0; i < MAXSIZE; i++)
        {
            Push(&S, i);
        }
        printf("压满后 top = %d（MAXSIZE-1 = %d）\n", S.top, MAXSIZE - 1);
        if (Push(&S, 999) == ERROR)
        {
            printf("满栈再压 -> 被拒绝（已到 MAXSIZE-1）\n");
        }
    }

// 正常结束
    return 0;
}

