// ============ 为什么这样约定 ============
//
// 也有人让 top 指向"栈顶上面那个空位"，那样空栈是 top = 0。
// 两种写法都对，但**混用必出 bug**。本文件统一用"top 指栈顶元素"：
//
//   入栈：先 top++ ，再把元素放进 data[top]
//   出栈：先取走 data[top] ，再 top--
//
// 一句话记住：**top 永远指着有东西的那个格子**，它指向 -1 就是空。

// 元素类型
typedef int ElemType;

// 栈最多能装多少个
#define MAXSIZE 100

// 状态码
#define OK 1
#define ERROR 0

// 返回值类型
typedef int Status;

// 顺序栈 = 定长数组 + 栈顶下标
typedef struct
{
// 连续内存，和顺序表一样
    ElemType data[MAXSIZE];
// 栈顶元素的下标；-1 表示空栈
    int top;
} Stack;

// ============ 空栈的表示 ============
//
// 和顺序表一样，初始化什么都不用清，只改一个标记位。
// 只是这里的标记是 top = -1，而不是 length = 0。
//
// 注意 -1 这个值本身很讲究：它是**合法下标 0 的前一个**，
// 所以"top == -1"和"top == 0（有一个元素）"能区分得清清楚楚。
// 如果图省事用 0 表示空栈，就分不清"空"和"有一个元素"了。

// 传指针：要改调用者那张栈的 top
Status InitStack(Stack *S)
{
// 空栈：top 指向"不存在的位置"
    S->top = -1;
// 成功
    return OK;
}

// ============ 入栈的三步 ============
//
//   入栈前： 10  20  30  _   _     top = 2
//             0   1   2   3   4
//
//   ① top++   →  top 从 2 变成 3（指向那个空位）
//   ② 存数据  →  data[3] = 40
//
//   入栈后： 10  20  30  40  _     top = 3
//
// 顺序不能反：如果先把 data[top] 写成 40，就把原来的 30 覆盖掉了。
// （这一点和顺序表插入"要从后往前搬"是同一个道理：别踩还没读的数据。）
//
// ============ 判满是必须的 ============
//
// 什么时候满？top 已经顶到最后一个格子 MAXSIZE-1 的时候。
//
//   装满： 10  20  30  40  50     top = 4 = MAXSIZE-1
//           0   1   2   3   4
//
// 这时再来一个，top++ 会让 top 变成 5，data[5] 就越界了。
// C 语言不会帮你检查数组越界 —— 它会闷头写进去，踩坏旁边的内存，
// 然后你在别的地方看到莫名其妙的错。所以**判满必须自己写**。

// 压入一个元素 e
Status Push(Stack *S, ElemType e)
{
// 第一步永远是判满 —— 顺序栈的容量是固定的
// 注意比较的是 MAXSIZE-1（最后一个合法下标），不是 MAXSIZE。
// 写成 top >= MAXSIZE 就晚了：那时候已经越界了。
    if (S->top >= MAXSIZE - 1)
    {
// 满了就拒绝，而不是硬塞
        return ERROR;
    }

// 先让 top 指向那个空位
    S->top++;

// 再放进去 —— 此时 top 正好指着新元素
    S->data[S->top] = e;

// 成功
    return OK;
}

// ============ 出栈是入栈的镜像 ============
//
//   出栈前： 10  20  30  40  _     top = 3
//
//   ① 取数据  →  e = data[3] = 40
//   ② top--   →  top 从 3 变成 2
//
//   出栈后： 10  20  30  40  _     top = 2
//                              ↑
//                        40 还在数组里，但已经"不属于这张栈"了
//
// 这一点很重要：**出栈并不擦除数据**，只是把 top 往回挪一格。
// 这和顺序表删除一样 —— 数据还在，但 length/top 说不算就不算。
//
// 下次入栈会直接把这格覆盖掉。所以出栈后**别再去读 data[top+1]**，
// 那个值随时可能被冲掉。
//
// ============ 判空也是必须的 ============
// 空栈时 top = -1。这时候如果去读 data[-1]，那是数组前面的内存,
// 读到的是别的变量的值 —— 不会崩，但结果完全是荒唐的。

// e 是"带回栈顶元素"的出口参数
Status Pop(Stack *S, ElemType *e)
{
// 第一步永远是判空
// 注意是 top == -1 而不是 top == 0：top = 0 时栈里有**一个**元素，
// 那是可以正常出栈的。
    if (S->top < 0)
    {
// 空栈不能再出
        return ERROR;
    }

// 先把栈顶元素取出来
    *e = S->data[S->top];

// 再把 top 往回挪一格 —— 这一格从此不算数了
    S->top--;

// 成功
    return OK;
}

// ============ 用输出验证"后进先出" ============
//
// 依次压入 10、20、30，再连续弹出，出来的顺序是 30、20、10 ——
// 和进去的顺序**正好相反**。这就是 LIFO（Last In First Out）。
//
// 别小看这一条：后面表达式求值、括号匹配、递归、DFS 全靠它。

// 打印当前栈里的内容（从栈底到栈顶）
static void PrintStack(const char *tag, Stack S)
{
    int i;

    printf("%s top=%d : ", tag, S.top);
    for (i = 0; i <= S.top; i++)
    {
        printf("%d ", S.data[i]);
    }
    printf("\n");
}

// 主函数
int main(void)
{
// 定义一张栈
    Stack S;
// 用来接住弹出的元素
    ElemType e;

// 先初始化
    InitStack(&S);
    PrintStack("初始化后:", S);

// 依次压入 10、20、30
    Push(&S, 10);
    Push(&S, 20);
    Push(&S, 30);
    PrintStack("压入 10 20 30 后:", S);

// 弹一个出来 —— 应该是最后进去的 30
    if (Pop(&S, &e) == OK)
    {
        printf("弹出一个 -> %d（最后进去的最先出来）\n", e);
    }
    PrintStack("弹出后:", S);

// 把剩下的都弹光，看顺序
    printf("继续弹出: ");
    while (Pop(&S, &e) == OK)
    {
        printf("%d ", e);
    }
    printf("\n");
    PrintStack("弹空后:", S);

// 空栈再弹应该被挡住
    if (Pop(&S, &e) == ERROR)
    {
        printf("空栈弹出 -> 被拒绝（top == -1）\n");
    }

// 压满再压一个，也应该被挡住
// 这一次循环压 MAXSIZE 个，正好压满（top 到 MAXSIZE-1）
    {
        int i;
        for (i = 0; i < MAXSIZE; i++)
        {
            Push(&S, i);
        }
        printf("压满后 top = %d（MAXSIZE-1 = %d）\n", S.top, MAXSIZE - 1);
        if (Push(&S, 999) == ERROR)
        {
            printf("满栈再压 -> 被拒绝（已到 MAXSIZE-1）\n");
        }
    }

// 正常结束
    return 0;
}

